from models.analytics import Analyticsfrom models.invoice import Invoicefrom models.payment import Paymentclass ReportService:    @staticmethod    def generate_revenue_report():        return {            "total_revenue": Analytics.total_revenue(),            "monthly_revenue": Analytics.monthly_revenue(),            "revenue_status": ReportService.get_revenue_status()        }    @staticmethod    def generate_invoice_report():        invoices = Invoice.get_all()        return {            "total_invoices": len(invoices),            "invoices": invoices        }    @staticmethod    def generate_payment_report():        payments = Payment.get_all()        successful = 0        failed = 0        pending = 0        for payment in payments:            status = payment[3]            if status == "success":                successful += 1            elif status == "failed":                failed += 1            else:                pending += 1        return {            "total_payments": len(payments),            "successful_payments": successful,            "failed_payments": failed,            "pending_payments": pending,            "payments": payments        }    @staticmethod    def get_revenue_status():        total_revenue = Analytics.total_revenue()        if total_revenue >= 100000:            return "High Revenue"        elif total_revenue >= 50000:            return "Medium Revenue"        else:            return "Low Revenue"